// The Android shell of the Keystead app (generated by `tauri android init`,
// hardened by hand – a unit test in src-tauri/src/gui.rs guards it; see
// "Mobile (Android)" in docs/ARCHITECTURE.md). Everything else is the
// Tauri runtime: TauriActivity (generated into `generated/` at build time)
// loads the Rust library, which builds the webview and the UI.
package io.github.cedrickgd.keystead

import android.os.Bundle
import android.view.View
import android.view.WindowManager
import android.webkit.WebView
import androidx.activity.OnBackPressedCallback
import androidx.activity.enableEdgeToEdge
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat

class MainActivity : TauriActivity() {
  private var webView: WebView? = null

  // The back gesture / button (see onBack). TauriActivity leaves it
  // unhandled (`handleBackNavigation = false`), but Tauri's own AppPlugin
  // adds a callback of its own that calls `webView.goBack()` whenever the
  // page has history – so ours is moved on top in onWebViewCreate.
  private val backCallback = object : OnBackPressedCallback(true) {
    override fun handleOnBackPressed() {
      onBack()
    }
  }

  override fun onCreate(savedInstanceState: Bundle?) {
    enableEdgeToEdge()
    super.onCreate(savedInstanceState)
    // Revealed passwords, card numbers and the recovery key must not end up
    // in screenshots, screen recordings or the recents thumbnail – the
    // phone's counterpart of the desktop's WDA_EXCLUDEFROMCAPTURE (Tauri's
    // `contentProtected` is a no-op on Android).
    window.setFlags(
      WindowManager.LayoutParams.FLAG_SECURE,
      WindowManager.LayoutParams.FLAG_SECURE
    )
    // Edge-to-edge (above) draws the window behind the status bar, the
    // gesture bar, a display cutout and the keyboard. Android's WebView
    // reports at most the cutout to the page (`env(safe-area-inset-*)`),
    // and `adjustResize` does nothing for an edge-to-edge window: the UI's
    // header would sit under the status bar and the keyboard would cover a
    // focused field. So the content view – the webview's parent (wry calls
    // `setContentView(webView)`) – is padded by exactly these insets and
    // consumes them: the webview gets the free area and shrinks while the
    // keyboard is open. The padding shows the window background
    // (`windowBackground` in res/values*/themes.xml: the UI's background
    // colour in light and dark).
    val content = findViewById<View>(android.R.id.content)
    ViewCompat.setOnApplyWindowInsetsListener(content) { view, insets ->
      val free = insets.getInsets(
        WindowInsetsCompat.Type.systemBars() or
          WindowInsetsCompat.Type.displayCutout() or
          WindowInsetsCompat.Type.ime()
      )
      view.setPadding(free.left, free.top, free.right, free.bottom)
      WindowInsetsCompat.CONSUMED
    }
    // Registered now so the gesture is ours before the webview exists too
    // (AppPlugin's callback, added after this, hands it on while there is
    // no page history); moved on top in onWebViewCreate.
    onBackPressedDispatcher.addCallback(this, backCallback)
  }

  // Called by the runtime once the webview exists (before the UI loads).
  override fun onWebViewCreate(webView: WebView) {
    super.onWebViewCreate(webView)
    this.webView = webView
    // The UI is served from the app's own origin (tauri.localhost) and never
    // loads anything else: no file://, content:// or geolocation access.
    webView.settings.apply {
      allowFileAccess = false
      allowContentAccess = false
      setGeolocationEnabled(false)
      safeBrowsingEnabled = false
    }
    // The dispatcher asks the most recently added callback first. The Rust
    // side registers every plugin – AppPlugin with its back callback –
    // before it builds the webview, so re-adding ours here puts it above
    // all of them: the page always gets the gesture as `keystead:back`,
    // never as a history step.
    backCallback.remove()
    onBackPressedDispatcher.addCallback(this, backCallback)
  }

  // Dispatches `keystead:back` on `window`. A listener that calls
  // `preventDefault()` has consumed the gesture (closed a dialog, left the
  // detail view, …); otherwise the app goes to the background – without
  // finishing the activity, so an open vault stays open until the
  // background lock applies.
  private fun onBack() {
    val view = webView
    if (view == null) {
      moveTaskToBack(true)
      return
    }
    view.evaluateJavascript(BACK_SCRIPT) { handled ->
      if (handled != "true") {
        moveTaskToBack(true)
      }
    }
  }

  companion object {
    private const val BACK_SCRIPT =
      "(function(){var e=new Event('keystead:back',{cancelable:true});" +
        "window.dispatchEvent(e);return e.defaultPrevented;})()"
  }
}
